import {GROUP_NAMES,base,group,fmt,requiresCooking,totals} from './engine.js';
import {SOURCES,pairingAdvice,spiceSuggestions,preparationAdvice} from './guidance.js';
import {PORTION_SOURCES,FOOD_GROUP_LABELS,validatePeople} from './portions.js';
import {EQUIPMENT,sameFamily,methodsFor,preferredMethod,makeRows,generatePlan,estimateNutrition,localDate,periodRange,aggregateEntries} from './planner.js';
import {PrivateJournal} from './vault.js';

const $=s=>document.querySelector(s),app=$('#app'),dialog=$('#dialog');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,foods=[],images={},families=[],step=1,query='',category='all',page=1,plan=null,readingPerson=0,journalTab='meals',journalPeriod='day',journalDate=localDate(),journalPerson='',customStart=localDate(),customEnd=localDate(),pendingAction='',detailFoodId='',returnToCatalogue=false,busy=false,idleTimer;
const draft={people:[{type:'adult',age:'',sex:''}],ingredients:[],equipment:[],methods:{},custom:{},share:1/3};
let vault;try{vault=new PrivateJournal();}catch{vault=null;}
const food=id=>foods.find(f=>f.id===id),title=f=>base(f).replace(/\b\w/g,c=>c.toUpperCase()),state=f=>f.name.split(',').slice(1).join(', ').trim()||'As recorded';
const selected=f=>draft.ingredients.some(id=>sameFamily(food(id),f));
const photo=f=>{const p=images.byFoodId?.[f.id]||images[f.baseName];return `<img class="food-photo${p?.fit==='contain'?' photo-contain':''}" src="${esc((p?.src||'assets/food-placeholder.svg').replace(/^public\//,'').replace(/^\//,''))}" alt="" title="${esc(p?.alt||title(f))}" loading="lazy" decoding="async" width="44" height="44">`;};
const link=key=>{const s=SOURCES[key]||PORTION_SOURCES[key];return s?`<a href="${esc(s[1])}" target="_blank" rel="noopener">${esc(s[0])} ↗</a>`:'';};
const keys=()=>db.components.filter(c=>!['edible','energy_kj'].includes(c.key)).map(c=>c.key);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function route(){return location.hash.slice(1).split('?')[0]||'home';}
function navigate(to){if(dialog.open)dialog.close();if(location.hash==='#'+to)render();else location.hash=to;}
function showDialog(html){dialog.innerHTML=`<div class="dialog-top"><span class="eyebrow">Gursha</span><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">×</button></div>${html}`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function clearPlanningMemory(){plan=null;readingPerson=0;step=1;journalPerson='';query='';detailFoodId='';draft.people=[{type:'adult',age:'',sex:''}];draft.ingredients=[];draft.equipment=[];draft.methods={};draft.custom={};draft.share=1/3;}
function touchVault(){clearTimeout(idleTimer);if(vault?.unlocked)idleTimer=setTimeout(()=>lockVault('Your private journal locked after 10 minutes of inactivity.'),600000);}
function lockVault(message='Your private journal is locked.'){vault?.lock();clearTimeout(idleTimer);pendingAction='';clearPlanningMemory();if(dialog.open)dialog.close();if(route()==='meal')navigate('journal');else render();toast(message);}
async function updateJournal(mutator){
  if(!vault?.unlocked)throw Error('Unlock your private journal first.');
  const before=structuredClone(vault.data);try{mutator(vault.data);await vault.save();touchVault();}catch(error){if(vault.unlocked)vault.data=before;throw error;}
}
function render(){
  if(!db)return;
  document.querySelectorAll('.site-header nav a').forEach(a=>a.classList.toggle('active',a.hash===location.hash));
  if(route()==='plan')renderWizard();else if(route()==='meal'&&plan)renderMeal();else if(route()==='journal')renderJournal();else renderHome();
}
function renderHome(){app.innerHTML=`<section class="landing"><div class="landing-kicker"><span></span> A little intention. A more nourishing meal.</div><h1>Are you getting the<br>most out of your <em>food?</em></h1><p class="landing-description">Gursha helps you maximize the nutrition you get from your meals through smart ingredient pairings, strategic food processing, and the right spices</p><a href="#plan" class="primary hero-button">Plan a Meal <span>↗</span></a><p class="hero-note">Three simple steps. Made for your table.</p><div class="landing-steps" aria-label="How it works"><span><b>01</b> Your people</span><i></i><span><b>02</b> Your ingredients</span><i></i><span><b>03</b> Your kitchen</span></div><div class="landing-bottom"><span>Rooted in food science.</span><button class="text-button" data-document="sources">Understand the approach ↗</button><span>Private by choice. Saved on your device.</span></div></section>`;}
function wizardHeader(){return `<div class="page-heading"><a href="#home" class="back-link">← Back to Gursha</a><span class="eyebrow">A meal with a little more intention</span><h1>Let’s plan something nourishing.</h1></div><nav class="stepper" aria-label="Meal planning steps">${[['Your people','Who’s at the table'],['Ingredients','What you have'],['Preparation','What your kitchen can do']].map(([label,small],i)=>`<button data-step="${i+1}" ${i+1>step?'disabled':''} ${i+1===step?'aria-current="step"':''}><b>${i+1<step?'✓':String(i+1).padStart(2,'0')}</b><span>${label}<small>${small}</small></span></button>`).join('')}</nav>`;}
function renderWizard(){
  app.innerHTML=`<div class="planner-shell">${wizardHeader()}${step===1?peopleForm():step===2?ingredientsForm():preparationForm()}</div>`;
  if(step===2){$('#ingredient-query').value=query;$('#ingredient-group').value=category;renderIngredientGrid();renderSuggestions();}
}
function peopleForm(){return `<form id="people-form" class="form-panel"><div class="form-heading"><span class="eyebrow">Step 01 of 03</span><h2>Who are you cooking for?</h2><p>Small appetites, grown-up appetites, and everyone in between.</p></div><div class="people-settings"><label>People at the table<input type="number" id="people-count" min="1" max="12" value="${draft.people.length}" required></label><label>This meal’s share of daily food-group serves<select id="meal-share"><option value="0.25" ${draft.share===.25?'selected':''}>One quarter · 25%</option><option value="0.3333333333333333" ${Math.abs(draft.share-1/3)<.001?'selected':''}>About one third · 33%</option><option value="0.5" ${draft.share===.5?'selected':''}>One half · 50%</option><option value="1" ${draft.share===1?'selected':''}>A full day’s food · 100%</option></select></label></div><div class="people-list">${draft.people.map((p,i)=>`<fieldset class="person-row"><legend>Diner ${i+1}</legend><label>Age group<select data-person="${i}" data-field="type" required><option value="adult" ${p.type==='adult'?'selected':''}>Adult · 18+</option><option value="kid" ${p.type==='kid'?'selected':''}>Kid / teen · 2–17</option></select></label><label>Age in years<input type="number" data-person="${i}" data-field="age" min="${p.type==='kid'?2:18}" max="${p.type==='kid'?17:120}" value="${esc(p.age)}" required placeholder="${p.type==='kid'?'e.g. 8':'e.g. 30'}"></label><label>Gender / nutrition reference<select data-person="${i}" data-field="sex" required><option value="">Choose a reference</option><option value="female" ${p.sex==='female'?'selected':''}>Female</option><option value="male" ${p.sex==='male'?'selected':''}>Male</option></select></label></fieldset>`).join('')}</div><details class="reference-note"><summary>How the portion guide works</summary><p>Gursha uses Australian Government daily food-group serves by age and sex for people aged 2 and above. Published references use female/male categories. Choose the applicable reference for planning. Each meal uses the share you select, divided among foods in the same group. This is a transparent starting point for portions, not a personal calorie prescription.</p><p>The guide describes average heights and sedentary to moderate activity. Pregnancy, breastfeeding, high activity and medical needs require adapted advice. Optional spices use culinary amounts. Foods without a suitable serving reference require your own gram amount.</p><div class="source-links">${link('adults')}${link('children')}${link('sizes')}</div></details><div class="form-actions"><span class="quiet-label">Your details stay in memory unless you choose to save.</span><button class="primary" type="submit">Choose ingredients <span>→</span></button></div></form>`;}
function ingredientsForm(){return `<form id="ingredients-form"><div class="form-heading"><span class="eyebrow">Step 02 of 03</span><h2>Start with what you have.</h2><p>Choose ingredients. We’ll help you find what works well together.</p></div><div class="ingredients-layout"><section class="form-panel pantry"><div class="selected-pills">${draft.ingredients.length?draft.ingredients.map(id=>`<span><button type="button" data-food="${id}" title="View food state and nutrients">${esc(title(food(id)))}</button><button type="button" data-remove="${id}" aria-label="Remove ${esc(title(food(id)))}">×</button></span>`).join(''):'<p class="quiet-label">Your ingredients will appear here.</p>'}</div><div class="pantry-controls"><label class="search-field"><span aria-hidden="true">⌕</span><input type="search" id="ingredient-query" placeholder="Search the pantry…" aria-label="Search the pantry"></label><label><span class="sr-only">Food group</span><select id="ingredient-group"><option value="all">All food groups</option>${Object.entries(GROUP_NAMES).sort(([a],[b])=>a.localeCompare(b)).map(([id,label])=>`<option value="${id}" ${category===id?'selected':''}>${esc(label)}</option>`).join('')}</select></label></div><div id="ingredient-grid" class="ingredient-grid"></div><div id="ingredient-pages"></div><p class="fine-print">Reference photos show ingredient families. The exact raw or cooked description appears in each food’s details.</p></section><aside class="suggestions" id="suggestions" aria-label="Pairing and spice suggestions"></aside></div><div class="form-actions"><button class="secondary" type="button" data-step="1">← Your people</button><button class="primary" type="submit">Choose preparation <span>→</span></button></div></form>`;}
function filteredFamilies(){const q=query.trim().toLowerCase().replace(/injera/g,'enjera');const list=families.filter(f=>(category==='all'||group(f)===category)&&(!q||foods.some(v=>sameFamily(v,f)&&`${v.name} ${v.amharic||''} ${v.id}`.toLowerCase().includes(q))));if(q)list.sort((a,b)=>Number(!base(a).toLowerCase().includes(q))-Number(!base(b).toLowerCase().includes(q)));return list;}
function renderIngredientGrid(modal=false){
  const list=filteredFamilies(),count=Math.max(1,Math.ceil(list.length/12));page=Math.min(page,count);
  const cards=list.slice((page-1)*12,page*12).map(original=>{const f=food(draft.ingredients.find(id=>sameFamily(food(id),original)))||original;return `<article class="ingredient ${selected(f)?'selected':''}"><button type="button" class="ingredient-select" data-ingredient="${f.id}" aria-pressed="${selected(f)}">${photo(f)}<span><strong>${esc(title(f))}</strong><small>${esc(requiresCooking(f)?'Raw · needs cooking':/boiled|cooked|fried|grill|baked|roasted/i.test(f.name)?'Already cooked':/raw/i.test(f.name)?'Raw / fresh':'As recorded')}</small></span><b aria-hidden="true">${selected(f)?'✓':'+'}</b></button><button type="button" class="food-info" data-food="${f.id}" aria-label="Details for ${esc(f.name)}">i</button></article>`;}).join('');
  $(modal?'#catalogue-grid':'#ingredient-grid').innerHTML=cards||'<p class="no-results">No matching ingredients. Try another name or food group.</p>';
  $(modal?'#catalogue-pages':'#ingredient-pages').innerHTML=`<div class="pagination"><span>${list.length} ingredient families</span><button type="button" data-page="${page-1}" ${page===1?'disabled':''} aria-label="Previous ingredients">←</button><span>${page} / ${count}</span><button type="button" data-page="${page+1}" ${page===count?'disabled':''} aria-label="Next ingredients">→</button></div>`;
}
function renderSuggestions(){
  const items=draft.ingredients.map(id=>({id,grams:100})),advice=pairingAdvice(items,foods),blends=spiceSuggestions(items,foods);
  $('#suggestions').innerHTML=draft.ingredients.length?`<span class="eyebrow">Thoughtful additions</span><h3>Better together.</h3><p class="small-text">Pairing ideas for these ingredients. Final portions come next.</p>${advice.map(a=>`<article class="suggestion"><h4>${esc(a.title)}</h4><p>${esc(a.text)}</p>${a.add?`<button type="button" class="small-button" data-add="${a.add.id}">Add ${esc(title(a.add))} +</button>`:''}<details><summary>Why this pairing?</summary>${link(a.source)}</details></article>`).join('')||'<p class="small-text muted">There isn’t a supported nutrient interaction to highlight yet. Each food’s individual reading is still available.</p>'}<details class="spice-options" open><summary>Finish with spices</summary>${blends.map(b=>`<article class="spice-option"><strong>${esc(b.title)}</strong><p>${esc(b.text)}</p><button type="button" class="text-button" data-blend="${b.id}" ${b.foods.every(selected)?'disabled':''}>${b.foods.every(selected)?'Added ✓':'Use this combination +'}</button><details><summary>How & why</summary><p>${esc(b.how)}</p>${link(b.source)}</details></article>`).join('')}</details>`:`<div class="suggestion-empty"><span>✧</span><h3>A few ingredients.<br>A little more possibility.</h3><p>Start with two or three foods to explore pairings and optional spices.</p><button class="text-button" type="button" data-action="example-ingredients">Try lentils, tomato & avocado ↗</button></div>`;
}
function preparationForm(){
  return `<form id="preparation-form"><div class="form-heading"><span class="eyebrow">Step 03 of 03</span><h2>What’s in your kitchen?</h2><p>Choose your equipment, then a practical method for each ingredient.</p></div><section class="form-panel"><div class="equipment-grid">${EQUIPMENT.map(([id,label])=>`<label class="equipment-option"><input type="checkbox" data-equipment="${id}" ${draft.equipment.includes(id)?'checked':''}><span>${label}</span></label>`).join('')}</div><p class="fine-print">No equipment? Leave these unchecked and use fresh or already-prepared foods.</p><div class="method-list">${draft.ingredients.map(id=>methodRow(food(id))).join('')}</div></section><div class="form-actions"><button class="secondary" type="button" data-step="2">← Ingredients</button><button class="primary" type="submit">Make my meal plan <span>↗</span></button></div></form>`;
}
function methodRow(f){
  const options=methodsFor(f,draft.equipment),chosen=options.some(m=>m.id===draft.methods[f.id])?draft.methods[f.id]:preferredMethod(f,draft.equipment);draft.methods[f.id]=chosen;
  let row;try{row=makeRows([f.id],draft.equipment,draft.methods,foods,draft.custom)[0];}catch{}
  const guide=preparationAdvice(f);
  return `<article class="method-row"><div class="method-identity">${photo(f)}<div><strong>${esc(title(f))}</strong><small>${esc(state(f))}</small></div></div><label>Preparation method<select data-method="${f.id}" required ${!options.length?'aria-invalid="true"':''}><option value="">${options.length?'Choose a method':'Add suitable equipment or change the food state'}</option>${options.map(m=>`<option value="${m.id}" ${chosen===m.id?'selected':''}>${esc(m.label)}</option>`).join('')}</select></label>${row?`<p class="method-basis">${esc(row.reference.basis)}</p>${row.reference.group==='manual'?`<label class="custom-grams">Edible grams per diner <span class="muted">in the ${['boil','steam','roast','microwave'].includes(chosen)?'cooked':'selected'} state</span><input type="number" data-custom="${f.id}" min="0.1" max="5000" step="0.1" value="${esc(draft.custom[f.id]||'')}" placeholder="Your own measured amount" required></label>`:''}${!row.profile?'<p class="coverage-note">No matching nutrient profile exists for this method. Its nutrients will be marked unknown, not counted as zero.</p>':''}`:'<p class="coverage-note">This food needs a suitable method before the plan can be generated. Raw cassava requires a verified safe processing recipe beyond this app’s scope.</p>'}<details class="method-guidance"><summary>Nutrition tip & food details</summary><strong>${esc(guide.method)}</strong><p>${esc(guide.text)}</p>${link(guide.source)}<button type="button" class="text-button" data-food="${f.id}">Change recorded food state ↗</button></details></article>`;
}
function nutrientValue(t,key,count){return((t.missing[key]||0)>=count||!Object.hasOwn(t.values,key))&&count>0?'—':fmt(t.values[key]||0)+(t.missing[key]||t.flagged[key]?'*':'');}
function nutritionBlock(t,count,full=true){
  return `<div class="nutrition-strip">${[['energy_kcal','Energy','kcal'],['protein','Protein','g'],['carbohydrate','Carbs','g'],['fat','Fat','g'],['fiber','Fiber','g']].map(([key,label,unit])=>`<div><small>${label}</small><strong>${nutrientValue(t,key,count)} <span>${unit}</span></strong></div>`).join('')}</div>${full?`<details class="nutrient-details"><summary>Micronutrients & full nutrition</summary><div class="table-scroll"><table><thead><tr><th>Nutrient</th><th>Selected amount</th><th>Data coverage</th></tr></thead><tbody>${db.components.filter(c=>!['edible','energy_kj'].includes(c.key)).map(c=>`<tr><th>${esc(c.label)}</th><td>${nutrientValue(t,c.key,count)} ${esc(c.unit)}</td><td>${Math.max(0,count-(t.missing[c.key]||0))} / ${count} ingredient readings${t.flagged[c.key]?` · ${t.flagged[c.key]} flagged`:''}</td></tr>`).join('')}</tbody></table></div></details>`:''}<p class="fine-print">* Partial coverage or flagged source values. — = unknown. Values estimate food content, not absorption. kcal are converted from recorded kJ where needed (4.184 kJ = 1 kcal), and marked with *. Missing nutrients and unavailable processed profiles are never treated as measured zero.</p>`;
}
function renderMeal(){
  readingPerson=Math.min(readingPerson,plan.people.length-1);const person=plan.people[readingPerson],t=estimateNutrition(person.items,foods,keys());
  app.innerHTML=`<section class="meal-result"><div class="result-heading"><a class="back-link" href="#plan">← Edit your meal</a><span class="eyebrow">Made for your table</span><h1>A little intention.<br>A more nourishing meal.</h1><p>${plan.people.length} ${plan.people.length===1?'diner':'diners'} · ${Math.round(plan.share*100)}% of daily food-group serves · ${plan.ingredients.length} ingredients</p></div><div class="result-toolbar"><label class="meal-title-label">Give this meal a name<input id="meal-title" value="${esc(plan.title)}" maxlength="120" required></label><button class="secondary" data-action="save-meal">Save meal <span>＋</span></button><button class="primary" data-action="log-meal">Log a serving <span>→</span></button></div><div class="result-layout"><section><div class="section-heading"><span class="eyebrow">Your preparation sequence</span><h2>From ingredients to a meal.</h2></div><ol class="cooking-sequence">${plan.steps.map((s,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p>${s.source?`<div class="source-links">${link(s.source)}</div>`:''}</div></li>`).join('')}</ol>${plan.pairings.length?`<details class="reference-note"><summary>Why these foods work together</summary>${plan.pairings.map(a=>`<h4>${esc(a.title)}</h4><p>${esc(a.text)}</p>${link(a.source)}`).join('')}</details>`:''}</section><aside class="result-sidebar"><section class="form-panel"><span class="eyebrow">What to prepare</span><h2>For the whole table.</h2><div class="batch-list">${plan.ingredients.map((r,i)=>`<div>${photo(food(r.ingredientId))}<span><strong>${esc(title(food(r.ingredientId)))}</strong><small>${esc(plan.rows[i].profileId?state(food(plan.rows[i].profileId)):plan.rows[i].method+' · profile unavailable')}</small></span><b>${fmt(r.grams)} g</b></div>`).join('')}</div><p class="fine-print">Cooked amounts are targets to weigh after preparation; raw-to-cooked yields are not guessed. Blend/grind amounts describe the original ingredient before adding water.</p></section><section class="form-panel person-nutrition"><label>Nutrition & portions for<select id="reading-person">${plan.people.map((p,i)=>`<option value="${i}" ${i===readingPerson?'selected':''}>${esc(p.person.label)} · age ${p.person.age} · ${p.person.sex}</option>`).join('')}</select></label>${nutritionBlock(t,person.items.length)}<details><summary>Individual ingredient portions</summary><ul class="portion-list">${person.items.map(r=>`<li><span>${esc(title(food(r.ingredientId)))}</span><strong>${fmt(r.grams)} g</strong></li>`).join('')}</ul><p class="fine-print">${link(person.daily.source)} · ${link('sizes')}</p></details></section></aside></div><details class="reference-note"><summary>Portions, sources & the rest of your day</summary><p>For each represented food group: this diner’s daily recommended serves × meal share ÷ number of chosen foods in that group × standard serve weight. Legumes are counted once as protein foods. Spices and avocado have culinary starting amounts. Custom portions are your own inputs, not guideline-derived recommendations.</p><p>Food groups missing from this meal are not silently replaced by another group. Include variety across the rest of your day. This is a preparation sequence and serving guide, not a guarantee that one meal meets every nutritional need.</p><div class="source-links">${Object.keys(PORTION_SOURCES).map(link).join('')}<a href="data/source-table.pdf" target="_blank" rel="noopener">Ethiopian Food Composition Table 2025 ↗</a></div></details><div class="form-actions"><a href="#plan" class="secondary">Adjust this plan</a><button class="text-button" data-action="print">Print preparation steps ↗</button></div></section>`;
}

function renderJournal(){
  if(!vault){app.innerHTML='<section class="private-intro"><h1>Private storage is unavailable.</h1><p>Enable browser storage to use the encrypted journal. You can still plan meals without saving.</p><a class="primary" href="#plan">Plan a Meal →</a></section>';return;}
  if(!vault.unlocked){app.innerHTML=`<section class="private-intro"><span class="lock-symbol" aria-hidden="true">⌑</span><span class="eyebrow">Your own little meal book</span><h1>Your meals.<br>Kept yours.</h1><p>Save favorite meals and keep a nutrition journal, encrypted on this device. No account. No meal uploads.</p>${vaultForm()}${migrationHelp()}<button class="text-button" data-action="import-backup">Restore an encrypted backup ↗</button><details class="reference-note"><summary>What “on this device” means</summary><p>Your browser stores an encrypted journal. A passphrase unlocks it in memory; Gursha does not store that passphrase. It automatically locks after 10 minutes of inactivity. There is no password reset or server copy. Clearing browser data, changing browsers, or moving to a different domain can remove access, so export encrypted backups.</p></details></section>`;return;}
  const data=vault.data;
  app.innerHTML=`<section class="journal-page"><div class="page-heading"><span class="eyebrow">Encrypted on this device</span><h1>Your meal book.</h1><p>A little record of what nourishes you.</p></div><div class="journal-toolbar"><div class="tab-buttons" role="group" aria-label="Meal book view"><button data-journal-tab="meals" class="${journalTab==='meals'?'active':''}" aria-pressed="${journalTab==='meals'}">Saved meals <span>${data.meals.length}</span></button><button data-journal-tab="intake" class="${journalTab==='intake'?'active':''}" aria-pressed="${journalTab==='intake'}">Nutrition journal</button></div><div><button class="text-button" data-action="export-backup">Export encrypted backup ↗</button><button class="small-button" data-action="lock">Lock</button></div></div>${journalTab==='meals'?`<div class="saved-meals">${data.meals.length?data.meals.map(m=>`<article class="saved-meal"><span class="eyebrow">${m.people.length} diners · ${m.ingredients.length} ingredients</span><h2>${esc(m.title)}</h2><p>${m.ingredients.slice(0,4).map(r=>food(r.ingredientId)?esc(title(food(r.ingredientId))):'Food from saved data').join(' · ')}</p><div><button class="small-button" data-view-meal="${esc(m.id)}">View & log →</button><button class="text-button" data-delete-meal="${esc(m.id)}">Remove</button></div></article>`).join(''):'<div class="empty-book"><h2>A place for your favorites.</h2><p>Plan a meal, then choose “Save meal” to keep it here.</p><a href="#plan" class="primary">Plan a Meal →</a></div>'}</div>`:intakeView()}<details class="journal-tools"><summary>Backups & privacy</summary><p>Your saved records are encrypted in this browser. Backups remain encrypted and need the same passphrase. There is no recovery service for a forgotten passphrase.</p><button class="text-button" data-action="import-backup">Restore / replace from encrypted backup ↗</button><button class="text-button danger" data-action="delete-vault">Delete this device’s journal</button></details></section>`;
}
function vaultForm(){const exists=vault?.exists();return `<form id="vault-form" class="vault-form"><label>${exists?'Your passphrase':'Choose a passphrase'}<input type="password" id="vault-passphrase" minlength="12" maxlength="1024" autocomplete="${exists?'current-password':'new-password'}" required placeholder="At least 12 characters"></label>${!exists?'<label>Confirm passphrase<input type="password" id="vault-confirm" minlength="12" maxlength="1024" autocomplete="new-password" required></label>':''}<p class="form-error" id="vault-error" role="alert"></p><button class="primary full-width" type="submit">${exists?'Unlock my meal book':'Create my private meal book'} <span>→</span></button></form>`;}
function requireVault(action){if(vault?.unlocked)return true;pendingAction=action;showDialog(`<h2 id="dialog-title">${vault?.exists()?'Unlock your meal book.':'Keep this meal, privately.'}</h2><p>Your saved meals and intake records are encrypted on this device. Your passphrase stays with you.</p>${vault?vaultForm():'<p>Browser storage is unavailable.</p>'}`);return false;}
function intakeView(){
  const entries=vault.data.entries,names=new Map(entries.map(e=>[e.personKey,e.personLabel]));if(!journalPerson||!names.has(journalPerson)&&journalPerson!=='all')journalPerson=[...names.keys()][0]||'all';
  const range=journalPeriod==='custom'?{start:customStart,end:customEnd}:periodRange(journalDate,journalPeriod),t=aggregateEntries(entries,range.start,range.end,journalPerson),count=t.entries.reduce((s,e)=>s+(e.ingredientCount||0),0); const energyDays=new Map();for(const e of t.entries)energyDays.set(e.date,(energyDays.get(e.date)||0)+(e.nutrition.values.energy_kcal||0));const chartMax=Math.max(1,...energyDays.values());
  return `<div class="journal-filters"><label>View<select id="journal-period">${[['day','Day'],['week','Week'],['month','Month'],['year','Year'],['custom','Custom range']].map(([id,label])=>`<option value="${id}" ${journalPeriod===id?'selected':''}>${label}</option>`).join('')}</select></label>${journalPeriod==='custom'?`<label>From<input type="date" id="range-start" value="${customStart}" max="${customEnd}"></label><label>To<input type="date" id="range-end" value="${customEnd}" min="${customStart}"></label>`:`<label>Date<input type="date" id="journal-date" value="${journalDate}"></label>`}<label>Whose intake?<select id="journal-person">${[...names.entries()].map(([key,label])=>`<option value="${esc(key)}" ${journalPerson===key?'selected':''}>${esc(label)}</option>`).join('')}<option value="all" ${journalPerson==='all'?'selected':''}>All profiles combined</option></select></label></div><section class="form-panel period-summary"><div class="section-heading"><span class="eyebrow">${range.start} — ${range.end}</span><h2>${journalPerson==='all'?'Combined profile totals':'Your recorded intake'}</h2><p>${t.count} logged ${t.count===1?'serving':'servings'}. Totals cover recorded foods only.</p></div>${nutritionBlock(t,count)}${t.count?`<div class="intake-bars" aria-label="Recorded energy by date">${[...new Set(t.entries.map(e=>e.date))].sort().slice(-31).map(date=>{const rows=t.entries.filter(e=>e.date===date),energy=rows.reduce((sum,e)=>sum+(e.nutrition.values.energy_kcal||0),0);return `<div><span>${date.slice(5)}</span><meter min="0" max="${chartMax}" value="${energy}" aria-label="${date}: ${fmt(energy,0)} recorded kcal"></meter><b>${fmt(energy,0)}</b></div>`;}).join('')}</div><p class="fine-print">Chart shows up to the last 31 recorded dates. Period totals above include the entire selected range. Values with missing nutrient data remain partial estimates.</p>`:''}</section><div class="intake-entries">${t.entries.length?t.entries.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<article><div><span class="eyebrow">${e.date} · ${esc(e.personLabel)} · ${esc(e.mealType)}</span><h3>${esc(e.title)}</h3><p>${e.fraction} × the selected diner’s portion · ${nutrientValue(e.nutrition,'energy_kcal',e.ingredientCount)} kcal</p></div><button class="text-button" data-delete-entry="${esc(e.id)}">Remove</button></article>`).join(''):'<div class="empty-book"><h2>Your next meal is a starting point.</h2><p>Choose “Log a serving” from a meal plan to record what you ate.</p><a href="#plan" class="primary">Plan a Meal →</a></div>'}</div>`;
}

function openCatalogue(){returnToCatalogue=true;showDialog(`<h2 id="dialog-title">A little ingredient knowledge.</h2><p>Explore the pantry, open an individual reading, or choose foods for your meal.</p><label class="search-field"><span aria-hidden="true">⌕</span><input type="search" id="catalogue-query" aria-label="Search the ingredient catalogue" value="${esc(query)}" placeholder="Lentils, tomato, teff…"></label><div id="catalogue-grid" class="ingredient-grid catalogue-grid"></div><div id="catalogue-pages"></div><button class="primary full-width" data-action="continue-planning">Plan with these ingredients <span>→</span></button>`);renderIngredientGrid(true);$('#catalogue-query').focus();}
function openFood(id){
  const f=food(id);if(!f)return;detailFoodId=id;
  const vs=foods.filter(v=>sameFamily(f,v)),p=images.byFoodId?.[id]||images[f.baseName];
  const t=estimateNutrition([{id,grams:100,knownProfile:true}],foods,keys()),a=preparationAdvice(f);
  showDialog(`<span class="eyebrow">Individual ingredient reading</span><div class="food-detail-heading">${photo(f)}<h2 id="dialog-title">${esc(title(f))}</h2></div><label>Recorded food state<select id="food-variant">${vs.map(v=>`<option value="${v.id}" ${v.id===id?'selected':''}>${esc(state(v))}</option>`).join('')}</select></label><p class="fine-print">Exact source: ${esc(f.name)} · EFCT ${f.id}. Nutrients below describe 100 g edible food in this state.</p>${nutritionBlock(t,1)}<details class="reference-note"><summary>Original values & source quality</summary><div class="table-scroll"><table><thead><tr><th>Component</th><th>Printed / recorded per 100 g</th><th>Source</th></tr></thead><tbody>${db.components.map(c=>`<tr><th>${esc(c.label)}</th><td>${esc(c.key.startsWith('energy_')?fmt(f.nutrients[c.key]):f.raw?.[c.key]??'—')} ${esc(c.unit)}</td><td><a href="data/source-table.pdf#page=${f.pages[c.section]}" target="_blank" rel="noopener">p. ${f.pages[c.section]} ↗</a>${f.quality?.[c.key]?.length?`<small>${esc(f.quality[c.key].join(', '))}</small>`:''}${f.nonAfrican?.[c.key]?'<small>oa</small>':''}</td></tr>`).join('')}</tbody></table></div><p class="fine-print">tr = trace · nd = not detected · [ ] = lower quality · oa = source outside Africa. Apparent source anomalies remain inspectable but are excluded from calculations.</p>${(f.sourceNotes||[]).map(n=>`<p class="fine-print">${esc(n)}</p>`).join('')}</details><section class="food-tip"><h3>${esc(a.method)}</h3><p>${esc(a.text)}</p>${link(a.source)}</section><p class="fine-print">${esc(p?.alt||'Ingredient-family reference image')}. ${p?.src?`<a href="${esc(p.source)}" target="_blank" rel="noopener">${esc(p.credit||'Original photo')}</a> · <a href="${esc(p.licenseUrl||p.source)}" target="_blank" rel="noopener">${esc(p.license||'License')}</a>`:'Reference image unavailable.'}</p><div class="dialog-actions">${returnToCatalogue?'<button class="secondary" data-action="back-catalogue">← Ingredients</button>':''}<button class="primary" data-action="use-food">Use this food state <span>＋</span></button></div>`);
}
function documentContent(which){
  const content={
    privacy:['Privacy, by design.',`<p>Updated 25 October 2026. Gursha is operated by Carlo Ertola. Meal planning does not require an account. Diner ages, nutrition-reference categories, selected foods and equipment remain in page memory until you choose to save a meal or log a serving.</p><h3>Your device, your journal</h3><p>Optional saved meals and intake records are encrypted with AES-256-GCM in this browser’s local storage. A PBKDF2-SHA256 key is derived from your passphrase with a random salt and at least 310,000 iterations. The passphrase and usable key are not saved. Unlocking decrypts records in page memory. The journal locks after ten minutes of inactivity or when you choose Lock.</p><p>No meal data, diner profiles or journal entries are uploaded by Gursha. Clearing browser data, private browsing, a lost device or a changed website origin can remove access. Export encrypted backups and keep your passphrase safe; there is no recovery service. Encryption does not protect data displayed in an unlocked browser or a compromised device.</p><h3>Hosting, cookies & links</h3><p>The hosting provider receives ordinary requests needed to deliver static files and may retain access logs such as IP address and browser information. Gursha sets no analytics or advertising cookies. Fonts and ingredient images are served locally. An offline cache stores app files and public food data, never your decrypted journal. External reference and social links have their own privacy practices.</p><p>Use the journal’s export, remove and delete controls to manage your data. For questions, contact <a href="mailto:info@carloertola.com">info@carloertola.com</a>; do not email passwords or private meal records.</p>`],
    terms:['A thoughtful starting point.',`<p>Gursha provides general food information, a preparation sequence and reference-based portion estimates. It does not provide a clinical diet, disease treatment, allergy diagnosis or a guarantee that a meal meets every nutrient need. Published serving tables describe populations; individual requirements can differ.</p><p>Confirm ingredients, allergies, source descriptions, food safety, cooking conditions and amounts yourself. Food photographs do not establish species or allergy safety. Ages below two, pregnancy, breastfeeding and medical dietary needs require advice adapted to those circumstances. No nutrient gain or absorption percentage is guaranteed.</p><p>Food composition varies by cultivar, recipe, storage and processing. Missing values stay unknown. Raw and cooked portions use distinct recorded states; the app does not invent cooking yields or retention factors. Ingredient additions and discarded solids can change what is consumed.</p><p>Keep encrypted backups and protect your passphrase. Gursha has no server copy and cannot recover a lost journal. These terms do not exclude rights that cannot lawfully be excluded. Contact <a href="mailto:info@carloertola.com">info@carloertola.com</a> for support.</p>`],
    accessibility:['A place at the table for everyone.',`<p>Gursha uses semantic headings, labeled inputs, native form validation, keyboard-operable buttons, visible focus indicators and dialogs. The layout adapts to narrow screens and browser zoom. Text accompanies images and data coverage markers. Reduced-motion preferences are respected.</p><p>Use the Skip to content link to reach the main area. Press Escape to close a dialog or footer menu. Nutrition tables can be scrolled horizontally when necessary. Use your browser’s print command or “Print preparation steps” to print a plan.</p><p>If you encounter a barrier, email <a href="mailto:info@carloertola.com">info@carloertola.com</a> with the page and what you were trying to do. We welcome practical suggestions and can discuss alternatives.</p>`],
    sources:['Food knowledge. Honest limits.',`<h3>Food composition</h3><p>Ethiopian Public Health Institute (EPHI) and FAO. 2025. <em>The Ethiopian Food Composition Table 2025.</em> Addis Ababa. © EPHI 2025. Reused with acknowledgement. No endorsement is implied. The import includes ${foods.length} distinct food codes and preserves trace markers, missing values, lower-quality brackets and source notes. Apparent source anomalies are excluded from totals.</p><p><a href="data/source-table.pdf" target="_blank" rel="noopener">Read the original food table ↗</a> · <a href="data/foods.json" download>Imported food data</a> · <a href="data/data-audit.json" target="_blank" rel="noopener">Import audit</a></p><h3>Portions</h3><p>Australian Government Eat for Health daily standard serves are used by age and sex, for ages 2+. A chosen fraction of daily serves is divided equally among selected foods within each group. Standard serve gram amounts are then applied to the selected state. This meal-allocation rule is Gursha’s planning convention, not a separate published meal prescription. Custom foods need user-entered gram amounts. An absent food group is never replaced automatically by more of a different group.</p><p>Cooked grain uses a 100 g planning value within the reference’s 75–120 g range. Bread/flatbread weights are applied as a proxy to injera. Legumes are counted once, as protein foods. Oils use the middle of the published daily allowance range. Spices and avocado use small culinary starting amounts, not nutrient-based recommendations. Milk measured in ml needs a user-measured gram weight rather than an assumed density.</p><div class="source-links">${Object.keys(PORTION_SOURCES).map(link).join('')}</div><h3>Pairings & processing</h3><p>Supported opportunities include plant iron with vitamin C and carotenoids with dietary fat. Practical display thresholds are 1 mg iron, 10 mg vitamin C, 300 µg beta-carotene and 2 g fat per chosen ingredient amount. These are filters, not clinical cutoffs. Suggestions do not calculate absorption or rank foods by a universal health score. Nutrient readings use the selected raw/cooked state, with no invented processing correction. Where only kJ is recorded, energy is converted to kcal using 4.184 kJ per kcal, flagged as derived; printed source values stay unchanged.</p><p>Spice combinations are mainly culinary. The mustard-with-cooked-broccoli suggestion links a small human study; optional black pepper was not part of its tested effect. Turmeric supplement findings do not establish health benefits from culinary portions. Preparation tips and safety instructions link the corresponding source.</p><ul class="source-list">${Object.keys(SOURCES).map(key=>`<li>${link(key)}</li>`).join('')}</ul><h3>Images & branding</h3><p>The Gursha logo is the image supplied by the project owner. Ingredient photographs and labeled AI-generated illustrations are family references; they do not verify the exact recipe, variety or species. Each individual food view links its original image and license. <a href="data/images.json" target="_blank" rel="noopener">Complete image credits ↗</a></p>`],
  }[which]||[];return content;
}
function openDocument(which){const [heading,body]=documentContent(which);showDialog(`<h2 id="dialog-title">${heading}</h2><div class="document-copy">${body}</div>`);$('.footer-legal').open=false;}
function syncTitle(){const input=$('#meal-title');if(input){if(!input.reportValidity())return false;plan.title=input.value.trim().slice(0,120);if(!plan.title){input.setCustomValidity('Give this meal a name.');input.reportValidity();return false;}}return true;}
async function saveMeal(){
  if(!plan||!syncTitle())return;if(!requireVault('save'))return;
  await updateJournal(data=>{if(data.meals.length>=500&&!data.meals.some(m=>m.id===plan.id))throw Error('Your meal book holds up to 500 recipes. Export a backup and remove a recipe first.');const saved=structuredClone(plan),index=data.meals.findIndex(m=>m.id===plan.id);if(index<0)data.meals.unshift(saved);else data.meals[index]=saved;});toast('Meal saved in your encrypted meal book.');
}
function logMealDialog(){
  if(!plan||!syncTitle())return;if(!requireVault('log'))return;
  showDialog(`<span class="eyebrow">Record what you actually ate</span><h2 id="dialog-title">A serving for your journal.</h2><form id="log-form"><label>Use the portion planned for<select id="log-person">${plan.people.map((p,i)=>`<option value="${i}" ${i===readingPerson?'selected':''}>${esc(p.person.label)} · age ${p.person.age} · ${p.person.sex}</option>`).join('')}</select></label><label>Whose intake are you tracking?<input id="log-person-label" maxlength="40" list="profile-labels" value="${readingPerson===0?'Me':'Diner '+(readingPerson+1)}" required><datalist id="profile-labels">${[...new Set(vault.data.entries.map(e=>e.personLabel))].map(label=>`<option value="${esc(label)}">`).join('')}</datalist></label><div class="two-fields"><label>Date eaten<input type="date" id="log-date" max="${localDate()}" value="${localDate()}" required></label><label>Meal<select id="log-type"><option>Breakfast</option><option>Lunch</option><option selected>Dinner</option><option>Snack</option></select></label></div><label>How much of that diner’s portion?<select id="log-fraction"><option value="0.25">One quarter · 25%</option><option value="0.5">One half · 50%</option><option value="0.75">Three quarters · 75%</option><option value="1" selected>One planned portion · 100%</option><option value="1.5">One and a half · 150%</option><option value="2">Two planned portions · 200%</option></select></label><p class="fine-print">This records one diner’s portion, not the entire household meal. Use a consistent profile label across meals. Nutrition remains an estimate with the data coverage shown in the plan.</p><p class="form-error" id="log-error" role="alert"></p><button class="primary full-width" type="submit">Save intake privately <span>→</span></button></form>`);
}
function importDialog(){showDialog(`<h2 id="dialog-title">Restore your meal book.</h2><p>Choose a Gursha encrypted JSON backup and the passphrase that protects it. Importing replaces the journal in this browser; export your current backup first if you want to keep it.</p><form id="import-form"><label>Encrypted backup<input id="backup-file" type="file" accept=".json,application/json" required></label><label>Backup passphrase<input id="backup-passphrase" type="password" minlength="12" maxlength="1024" autocomplete="off" required></label><label class="check-label"><input type="checkbox" id="replace-consent" required><span>Replace this browser’s journal with this backup.</span></label><p class="form-error" id="import-error" role="alert"></p><button class="primary full-width" type="submit">Restore encrypted backup →</button></form>`);}
function downloadBackup(){const blob=new Blob([vault.exportBackup()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`gursha-encrypted-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Encrypted backup exported. Keep your passphrase separately.');}
function confirmRemoval(kind,id=''){showDialog(`<h2 id="dialog-title">${kind==='vault'?'Delete this device’s journal?':kind==='meal'?'Remove this saved meal?':'Remove this intake entry?'}</h2><p>${kind==='vault'?'This removes every saved recipe and intake entry from this browser. Export an encrypted backup first if you want to restore them later.':kind==='meal'?'The recipe will leave your meal book. Previously logged intake stays in the journal.':'This entry will be removed from your recorded intake totals.'}</p><div class="dialog-actions"><button class="secondary" data-action="close-dialog">Keep it</button><button class="primary danger-button" data-confirm-remove="${kind}" data-id="${esc(id)}">${kind==='vault'?'Delete journal':'Remove'}</button></div>`);}
function toggleIngredient(id,addOnly=false){
  const f=food(id);if(!f)return;const existing=draft.ingredients.find(id=>sameFamily(food(id),f));
  if(existing){if(!addOnly)draft.ingredients=draft.ingredients.filter(x=>x!==existing);}else if(draft.ingredients.length<30)draft.ingredients.push(id);else toast('Choose up to 30 ingredients.');
  if(dialog.open&&$('#catalogue-grid'))renderIngredientGrid(true);else if(route()==='plan'&&step===2)renderWizard();
}
async function afterUnlock(){touchVault();if(dialog.open)dialog.close();const action=pendingAction;pendingAction='';if(action==='save')await saveMeal();else if(action==='log')logMealDialog();else render();}

document.addEventListener('click',async event=>{
  const el=event.target.closest('button,a');if(!el)return;const d=el.dataset;if(!db)return;touchVault();
  try{
    if(d.action==='close-dialog'){dialog.close();returnToCatalogue=false;return;}
    if(d.document){openDocument(d.document);return;}
    if(d.step){const next=Number(d.step);if(next===2&&!validatePeople(draft.people)){step=1;renderWizard();toast('Complete each diner’s details first.');return;}if(next===3&&(!validatePeople(draft.people)||!draft.ingredients.length)){toast('Complete the first two steps first.');return;}step=next;navigate('plan');return;}
    if(d.ingredient){toggleIngredient(d.ingredient);return;}
    if(d.add){toggleIngredient(d.add,true);return;}
    if(d.remove){draft.ingredients=draft.ingredients.filter(id=>id!==d.remove);renderWizard();return;}
    if(d.food){returnToCatalogue=!!$('#catalogue-grid');openFood(d.food);return;}
    if(d.page){page=Number(d.page);renderIngredientGrid(!!$('#catalogue-grid'));return;}
    if(d.blend){const blend=spiceSuggestions(draft.ingredients.map(id=>({id,grams:100})),foods).find(b=>b.id===d.blend);if(!blend)return;if(draft.ingredients.length+blend.foods.filter(f=>!selected(f)).length>30){toast('Make room for the spice combination first.');return;}blend.foods.forEach(f=>{if(!selected(f))draft.ingredients.push(f.id);});renderWizard();return;}
    if(d.action==='example-ingredients'){draft.ingredients=['030073','040030','050003'].filter(id=>food(id));renderWizard();return;}
    if(d.action==='use-food'){const f=food(detailFoodId);const old=draft.ingredients.find(id=>sameFamily(food(id),f));if(old)draft.ingredients=draft.ingredients.map(id=>id===old?f.id:id);else if(draft.ingredients.length<30)draft.ingredients.push(f.id);else{toast('Choose up to 30 ingredients.');return;}dialog.close();if(route()==='plan')renderWizard();else{step=1;navigate('plan');}toast('Recorded food state selected.');return;}
    if(d.action==='back-catalogue'){openCatalogue();return;}
    if(d.action==='continue-planning'){step=validatePeople(draft.people)?2:1;navigate('plan');return;}
    if(d.action==='save-meal'){await saveMeal();return;}
    if(d.action==='log-meal'){logMealDialog();return;}
    if(d.action==='print'){window.print();return;}
    if(d.action==='lock'){lockVault();return;}
    if(d.action==='export-backup'){downloadBackup();return;}
    if(d.action==='import-backup'){importDialog();return;}
    if(d.journalTab){journalTab=d.journalTab;renderJournal();return;}
    if(d.viewMeal){plan=structuredClone(vault.data.meals.find(m=>m.id===d.viewMeal));readingPerson=0;draft.people=plan.people.map(p=>({...p.person}));draft.ingredients=plan.rows.map(r=>r.ingredientId);draft.equipment=[...plan.equipment];draft.methods=Object.fromEntries(plan.rows.map(r=>[r.ingredientId,r.method]));draft.custom=Object.fromEntries(plan.rows.filter(r=>r.reference.group==='manual').map(r=>[r.ingredientId,plan.people[0].items.find(i=>i.ingredientId===r.ingredientId).grams]));draft.share=plan.share;step=3;navigate('meal');return;}
    if(d.deleteMeal){confirmRemoval('meal',d.deleteMeal);return;}
    if(d.deleteEntry){confirmRemoval('entry',d.deleteEntry);return;}
    if(d.action==='delete-vault'){confirmRemoval('vault');return;}
    if(d.confirmRemove){
      if(d.confirmRemove==='vault'){vault.storage.removeItem('gursha-private-v1');lockVault();toast('This browser’s journal was deleted.');}
      else{await updateJournal(data=>{if(d.confirmRemove==='meal')data.meals=data.meals.filter(m=>m.id!==d.id);else data.entries=data.entries.filter(e=>e.id!==d.id);});dialog.close();renderJournal();toast('Removed from your encrypted journal.');}return;
    }
  }catch(error){toast(error.message||'That change could not be saved.');}
});

document.addEventListener('submit',async event=>{
  const form=event.target;if(!['people-form','ingredients-form','preparation-form','vault-form','log-form','import-form'].includes(form.id))return;
  event.preventDefault();if(!form.reportValidity()||busy)return;const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;busy=true;
  try{
    if(form.id==='people-form'){if(!validatePeople(draft.people))throw Error('Complete every diner’s age, age group and nutrition reference.');step=2;query='';category='all';page=1;renderWizard();}
    if(form.id==='ingredients-form'){if(!draft.ingredients.length)throw Error('Choose at least one ingredient to continue.');if(draft.ingredients.every(id=>group(food(id))==='14'))throw Error('Add a main food as well as spices.');step=3;renderWizard();}
    if(form.id==='preparation-form'){plan=generatePlan(draft,foods,db.components);readingPerson=0;navigate('meal');}
    if(form.id==='vault-form'){
      const pass=$('#vault-passphrase').value;
      if(!vault.exists()){if(pass!==$('#vault-confirm').value)throw Error('The passphrases do not match.');await vault.create(pass);}else await vault.unlock(pass);
      $('#vault-passphrase').value='';if($('#vault-confirm'))$('#vault-confirm').value='';await afterUnlock();
    }
    if(form.id==='log-form'){
      const p=plan.people[Number($('#log-person').value)],fraction=Number($('#log-fraction').value),personLabel=$('#log-person-label').value.trim(),date=$('#log-date').value,mealType=$('#log-type').value;
      if(!personLabel||!p||![.25,.5,.75,1,1.5,2].includes(fraction)||date>localDate())throw Error('Check the profile, date and serving amount.');
      const items=p.items.map(r=>({...r,grams:r.grams*fraction})),entry={id:crypto.randomUUID(),mealId:plan.id,title:plan.title,personKey:personLabel.toLowerCase(),personLabel,date,mealType,fraction,ingredientCount:items.length,nutrition:estimateNutrition(items,foods,keys()),items};
      await updateJournal(data=>{if(data.entries.length>=10000)throw Error('Export a backup and remove older entries before adding more.');data.entries.push(entry);});dialog.close();journalPerson=entry.personKey;journalTab='intake';journalDate=date;navigate('journal');toast('Serving added to your encrypted nutrition journal.');
    }
    if(form.id==='import-form'){
      const f=$('#backup-file').files[0];if(!f||f.size>15*1024*1024)throw Error('Choose a Gursha backup smaller than 15 MB.');await vault.importBackup(await f.text(),$('#backup-passphrase').value);$('#backup-passphrase').value='';pendingAction='';touchVault();dialog.close();navigate('journal');toast('Encrypted backup restored on this device.');
    }
  }catch(error){const errorId={'vault-form':'vault-error','log-form':'log-error','import-form':'import-error'}[form.id];if(errorId&&$('#'+errorId))$('#'+errorId).textContent=error.message;else toast(error.message);}
  finally{busy=false;if(submit?.isConnected)submit.disabled=false;}
});
document.addEventListener('input',event=>{
  const el=event.target;touchVault();
  if(el.id==='global-search'&&el.value.trim()){query=el.value;page=1;category='all';openCatalogue();el.value='';}
  if(el.id==='catalogue-query'){query=el.value;page=1;renderIngredientGrid(true);}
  if(el.id==='ingredient-query'){query=el.value;page=1;renderIngredientGrid();}
  if(el.id==='people-count'){const count=Number(el.value);if(Number.isInteger(count)&&count>=1&&count<=12&&count!==draft.people.length){while(draft.people.length<count)draft.people.push({type:'adult',age:'',sex:''});draft.people=draft.people.slice(0,count);renderWizard();$('#people-count').focus();}return;}
  if(el.id==='meal-title')plan.title=el.value;
  if(el.dataset.person!==undefined&&el.dataset.field==='age')draft.people[Number(el.dataset.person)].age=el.value===''?'':Number(el.value);
  if(el.dataset.custom)draft.custom[el.dataset.custom]=el.value;
});
document.addEventListener('change',event=>{
  const el=event.target;
  if(el.id==='people-count'){
    const count=Number(el.value);if(!Number.isInteger(count)||count<1||count>12){el.reportValidity();return;}
    while(draft.people.length<count)draft.people.push({type:'adult',age:'',sex:''});draft.people=draft.people.slice(0,count);renderWizard();
  }
  if(el.dataset.person!==undefined){const p=draft.people[Number(el.dataset.person)];p[el.dataset.field]=el.dataset.field==='age'?Number(el.value):el.value;if(el.dataset.field==='type'){if((p.type==='kid'&&p.age>=18)||(p.type==='adult'&&p.age<18))p.age='';renderWizard();}}
  if(el.id==='meal-share')draft.share=Number(el.value);
  if(el.id==='ingredient-group'){category=el.value;page=1;renderIngredientGrid();}
  if(el.dataset.equipment){draft.equipment=el.checked?[...new Set([...draft.equipment,el.dataset.equipment])]:draft.equipment.filter(x=>x!==el.dataset.equipment);renderWizard();}
  if(el.dataset.method){draft.methods[el.dataset.method]=el.value;delete draft.custom[el.dataset.method];renderWizard();}
  if(el.id==='food-variant')openFood(el.value);
  if(el.id==='reading-person'){readingPerson=Number(el.value);renderMeal();}
  if(el.id==='log-person'){$('#log-person-label').value=Number(el.value)===0?'Me':`Diner ${Number(el.value)+1}`;}
  if(['journal-period','journal-date','journal-person','range-start','range-end'].includes(el.id)){
    if(el.id==='journal-period')journalPeriod=el.value;if(el.id==='journal-date'&&el.value)journalDate=el.value;if(el.id==='journal-person')journalPerson=el.value;if(el.id==='range-start'&&el.value)customStart=el.value;if(el.id==='range-end'&&el.value)customEnd=el.value;
    if(customStart>customEnd){toast('The start date must be before the end date.');return;}renderJournal();
  }
});
document.addEventListener('keydown',event=>{touchVault();if(event.key==='Escape'&&$('.footer-legal').open){$('.footer-legal').open=false;$('.footer-legal summary').focus();}if(event.key==='Enter'&&event.target.id==='global-search'){event.preventDefault();query=event.target.value;openCatalogue();}});
document.addEventListener('click',event=>{const footer=$('.footer-legal');if(!footer.contains(event.target))footer.open=false;});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
dialog.addEventListener('close',()=>dialog.querySelectorAll('input[type="password"]').forEach(input=>input.value=''));
window.addEventListener('hashchange',()=>{if(dialog.open)dialog.close();if(route()==='plan'&&!validatePeople(draft.people))step=1;render();window.scrollTo(0,0);});
window.addEventListener('storage',event=>{if(event.key==='gursha-private-v1'&&vault?.unlocked)lockVault('The journal changed in another tab and was locked. Unlock the latest copy.');});
window.addEventListener('pagehide',()=>{vault?.lock();clearPlanningMemory();});
window.addEventListener('pageshow',event=>{if(event.persisted&&db)render();});
async function init(){
  try{
    const [data,pictures]=await Promise.all([fetch('data/foods.json').then(r=>{if(!r.ok)throw Error('Food data unavailable');return r.json();}),fetch('data/images.json').then(r=>r.ok?r.json():{}).catch(()=>({}))]);db=data;foods=data.foods;images=pictures;
    const preferred=[/^Lentil,.*whole.*boiled.*drained/i,/^Tomato,.*raw/i,/^Avocado,.*raw/i,/^Carrot,.*raw/i,/^Chickpeas,.*boiled.*drained/i,/^Broccoli,.*raw/i,/^Ethiopian Kale,.*raw/i,/^Rice,.*boiled.*without salt/i,/^Egg,.*boiled/i,/^Orange,.*raw/i,/^Teff, whole.*raw/i,/^Linseed,.*raw/i];
    const map=new Map();for(const f of foods){const key=group(f)+':'+base(f).toLowerCase();if(!map.has(key)||requiresCooking(map.get(key))&&!requiresCooking(f))map.set(key,f);}
    for(const pattern of preferred){const f=foods.find(f=>pattern.test(f.name));if(f)map.set(group(f)+':'+base(f).toLowerCase(),f);}
    const rank=f=>{const i=preferred.findIndex(p=>p.test(f.name));return i<0?1000:i;};families=[...map.values()].sort((a,b)=>rank(a)-rank(b)||a.name.localeCompare(b.name));
    render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
  }catch(error){app.innerHTML='<section class="private-intro"><h1>The pantry couldn’t open.</h1><p>Check your connection and reload to try again.</p><button class="primary" id="retry">Try again</button></section>';$('#retry').onclick=init;console.error(error);}
}
